-- Review Demo Mode seed data
-- Generated from the isolated local demo database.
-- This file contains DEMO DATA ONLY.

CREATE TABLE IF NOT EXISTS demo_quotes (
            contract_symbol TEXT PRIMARY KEY,
            ticker TEXT NOT NULL,
            expiry TEXT NOT NULL,
            bid REAL NOT NULL,
            ask REAL NOT NULL,
            mark REAL NOT NULL
        );

CREATE TABLE IF NOT EXISTS demo_alerts (
            alert_id INTEGER PRIMARY KEY AUTOINCREMENT,
            state TEXT NOT NULL,
            ticker TEXT NOT NULL,
            direction TEXT NOT NULL,
            contract TEXT NOT NULL,
            quality TEXT NOT NULL,
            message TEXT NOT NULL,
            status TEXT NOT NULL
        );

